@@ -0,0 +1,21 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { stockValue } from "../src/domain/reports.js";
+import { fresh } from "./helpers.js";
+
+test("stock value sums independently rounded batch costs and ignores item prices", () => {
+  const store = fresh();
+  store.data.batches = [
+    { id: 1, itemId: 1, qty: 0.5, costCents: 101 },
+    { id: 2, itemId: 1, qty: 0.5, costCents: 201 },
+    { id: 3, itemId: 2, qty: 0.5, costCents: 1 },
+    { id: 4, itemId: 2, qty: 0, costCents: 999 },
+  ];
+  store.data.items[0].priceCents = 9999;
+  const report = stockValue(store);
+  assert.equal(report.totalCents, 153);
+  assert.deepEqual(report.lines[0], { itemId: 1, name: "onion", qty: 1, valueCents: 152 });
+  assert.equal(report.lines[1].valueCents, 1);
+  assert.equal(report.lines[2].valueCents, 0);
+  assert.equal(report.totalCents, report.lines.reduce((sum, line) => sum + line.valueCents, 0));
+});
